function drawHelmetAccent(ctx,kind,yTop){
  const accent={ivory:'#f5df9c',obsidian:'#8c99ae',amethyst:'#efc0ff',rose:'#f6accd'}[kind]||'#f5df9c';
  ctx.save(); ctx.fillStyle=accent; ctx.strokeStyle=accent; ctx.lineWidth=2.2;
  if(kind==='ivory'){ctx.beginPath();ctx.moveTo(-10,yTop+8);ctx.lineTo(0,yTop-28);ctx.lineTo(10,yTop+8);ctx.closePath();ctx.fill();}
  else if(kind==='obsidian'){ctx.beginPath();ctx.moveTo(-34,yTop+18);ctx.lineTo(-54,yTop+3);ctx.lineTo(-40,yTop+26);ctx.closePath();ctx.fill();ctx.beginPath();ctx.moveTo(34,yTop+18);ctx.lineTo(54,yTop+3);ctx.lineTo(40,yTop+26);ctx.closePath();ctx.fill();}
  else if(kind==='amethyst'){for(const dx of [-16,0,16]){ctx.beginPath();ctx.moveTo(dx-6,yTop+12);ctx.lineTo(dx,yTop-12-(dx===0?8:0));ctx.lineTo(dx+6,yTop+12);ctx.closePath();ctx.fill();}}
  else if(kind==='rose'){ctx.beginPath();ctx.moveTo(2,yTop+6);ctx.bezierCurveTo(28,yTop-18,38,yTop+8,20,yTop+28);ctx.bezierCurveTo(16,yTop+16,8,yTop+10,2,yTop+6);ctx.fill();ctx.globalAlpha=.8;ctx.beginPath();ctx.moveTo(-2,yTop+10);ctx.bezierCurveTo(-24,yTop-10,-32,yTop+10,-16,yTop+24);ctx.bezierCurveTo(-12,yTop+17,-7,yTop+13,-2,yTop+10);ctx.fill();}
  ctx.restore();
}
