function updateGuardUI(now){let circleDeg=360,label='READY',sub='SPACE',bg='#b9f0f6';if(now<s.blockTo){const frac=(s.blockTo-now)/2000;circleDeg=(1-frac)*360;label='GUARD';sub=((s.blockTo-now)/1000).toFixed(1)+'s';bg='#b8ebf7'}else if(now<s.blockReady){const frac=(s.blockReady-now)/5000;circleDeg=(1-frac)*360;label='COOLDOWN';sub=((s.blockReady-now)/1000).toFixed(1)+'s';bg='#f1b990'}$('guardCircle').style.background='conic-gradient('+bg+' '+circleDeg+'deg,#2b4b55 0)';$('guardInner').innerHTML=label+'<br><span style="font-size:10px;font-weight:500;opacity:.82">'+sub+'</span>'}
function update(now,dt){if(!s?.playing)return;if(isOnline){updateOnline(now,dt);return}
  if(now<s.battleStartsAt){const seconds=(now-s.preparationStart)/1000; const countText=seconds<1?'3':seconds<2?'2':seconds<3?'1':'DUEL!';if($('countNumber').textContent!==countText){$('countNumber').textContent=countText;$('countNumber').style.fontSize=seconds>=3?'clamp(72px,11vw,145px)':'';}if(!$('countdown').classList.contains('on'))$('countdown').classList.add('on');return}
  if($('countdown').classList.contains('on')){$('countdown').classList.remove('on');notify('STEEL AND WORDS!', '#f7dba6',950)}
  const target=stancePose(s.zone);const blend=1-Math.exp(-dt/125);s.pose.x+=(target.x-s.pose.x)*blend;s.pose.y+=(target.y-s.pose.y)*blend;s.pose.a+=(target.a-s.pose.a)*blend;if(s.feedback&&now>=s.feedbackUntil){let done=s.feedbackDone;s.feedback='';s.feedbackDone=null;makeCombo();if(done==='hit'&&s.foehp<=0){end(true);return}}if(!s.attackHitDone && now>=s.attackHitAt){
  s.attackHitDone=true;
  s.foehp=Math.max(0,s.foehp-12);
  s.foeStaggerStart=now;
  s.foeStaggerUntil=now+650;
  s.shake=6;
  particles(W*.5,H*.46,'#f8e7a6',37);
  if(s.enemyPendingInterrupt){
    s.enemyPendingInterrupt=false;
    s.enemyInterruptUntil=now+1050;
    // The prominent enemy-interruption banner handles this event.
    // Do not create a second toast with the same text.
  }else notify('HIT · 12 DAMAGE','#a6ffb1',480);
  hud();
}if(s.phase==='wait'&&now>=s.next){s.enemyZone=Z[Math.floor(Math.random()*3)];s.phase='windup';s.impact=now+2400;s.windupStart=now;s.enemyWord=['ember','castle','raven','squire','blade','shield'][Math.floor(Math.random()*6)];s.enemyTypedCount=0}if(s.phase==='windup'&&now>=s.impact){const block=now<=s.blockTo&&s.zone===s.enemyZone;s.phase='recover';s.next=now+1650;s.enemySwing=now+620;if(block){s.blocked=now+550;notify('BLOCKED','#bde9ee');particles(W*.51,H*.57,'#bdeafa',22)}else{s.myhp=Math.max(0,s.myhp-16);s.shake=12;s.hitTo=now+400;particles(W*.5,H*.64,'#f47d64',28);notify('WOUNDED · 16 DAMAGE','#ff9986');if(s.typed.length>0&&!s.feedback){s.typed='';s.interruptUntil=now+1000;$('interrupt').classList.add('on');hud();}if(s.myhp<=0)end(false)}hud()}if((s.phase==='recover'||s.phase==='stagger')&&now>=s.next){s.phase='wait';s.next=now+700}if(now-lastHudTick>=90){lastHudTick=now;updateGuardUI(now);} $('hurt').style.opacity=now<s.hitTo?'1':'0';$('interrupt').classList.toggle('on',now<s.interruptUntil);
$('enemyInterrupt').classList.toggle('on',now<s.enemyInterruptUntil);
$('foeTyping').classList.toggle('on',s.phase==='windup');
if(s.phase==='windup'){
  const count=Math.min(s.enemyWord.length,Math.floor((now-s.windupStart)/2400*s.enemyWord.length));if(count>s.enemyTypedCount){addTypedChars('enemy',count-s.enemyTypedCount,now);s.enemyTypedCount=count;}
  const nextText='ENEMY TYPING · '+s.enemyWord.slice(0,count).toUpperCase()+'▌';
  if($('foeTyping').textContent!==nextText)$('foeTyping').textContent=nextText;
}else if($('foeTyping').textContent)$('foeTyping').textContent='';
if(now>toastExpire)$('toast').classList.remove('on');s.particles=s.particles.filter(p=>p.life>0);for(const p of s.particles){p.x+=p.vx*dt/16;p.y+=p.vy*dt/16;p.vy+=.14*dt/16;p.life-=dt/16}s.shake*=.87}
function polygon(points,fill,stroke,lw=1){g.beginPath();g.moveTo(points[0][0],points[0][1]);for(let i=1;i<points.length;i++)g.lineTo(points[i][0],points[i][1]);g.closePath();g.fillStyle=fill;g.fill();if(stroke){g.lineWidth=lw;g.strokeStyle=stroke;g.stroke()}}function rect(x,y,w,h,col){g.fillStyle=col;g.fillRect(x,y,w,h)}function line(x,y,xx,yy,color,width=1){g.strokeStyle=color;g.lineWidth=width;g.beginPath();g.moveTo(x,y);g.lineTo(xx,yy);g.stroke()}function ellipse(x,y,rx,ry,col){g.fillStyle=col;g.beginPath();g.ellipse(x,y,rx,ry,0,0,Math.PI*2);g.fill()}
function castle(now){
 const sky=g.createLinearGradient(0,0,0,H);sky.addColorStop(0,'#73b3ee');sky.addColorStop(.44,'#d7ebf1');sky.addColorStop(.75,'#f8eacb');sky.addColorStop(1,'#b6bc84');rect(0,0,W,H,sky);
 const sun=g.createRadialGradient(W*.79,H*.16,10,W*.79,H*.16,W*.11);sun.addColorStop(0,'#fffde8d9');sun.addColorStop(.25,'#fff6c0b7');sun.addColorStop(1,'#ffffff00');rect(0,0,W,H,sun);
 for(let j=0;j<15;j++){let x=((j*251+now*.003*(j%3+1))%(W+320))-160,y=H*(.06+(j*19%36)/100);ellipse(x,y,W*.065,H*.03,'#f8ffffac');ellipse(x+W*.04,y-H*.008,W*.05,H*.036,'#f8ffffa0');ellipse(x-W*.04,y+H*.004,W*.05,H*.024,'#fffef2a0')}
 // distant hills
 for(let i=0;i<11;i++){let x=i*W/9-W*.05;polygon([[x-W*.18,H*.66],[x,H*(.37+(i%4)*.035)],[x+W*.20,H*.66]],i%2?'#8daebb':'#9eb6bd')}
 polygon([[W*.39,H*.67],[W*.51,H*.37],[W*.71,H*.36],[W*.82,H*.65]],'#a9ad93');
 // castle keep
 rect(W*.4,H*.34,W*.36,H*.28,'#d9ccb0');for(let i=0;i<19;i++){let x=W*(.4+i*.02);rect(x,H*.317,W*.012,H*.046,'#d6c2a8')}
 for(const [x,scale] of [[.42,1],[.55,1.43],[.71,1.05]]){let tx=W*x,tw=W*.06*scale,top=H*(.185-(scale-1)*.07);rect(tx-tw/2,top,tw,H*.49-top,'#cab99f');polygon([[tx-tw*.67,top],[tx,top-H*.105],[tx+tw*.67,top]],'#8297b2');rect(tx-W*.008,top+H*.075,W*.016,H*.062,'#6d7e8b');for(let i=0;i<4;i++)rect(tx-tw*.45+i*tw*.28,top-H*.014,tw*.18,H*.027,'#baa88f');for(let n=0;n<5;n++)rect(tx-tw*.42+n*tw*.21,top+H*.11,tw*.09,H*.02,'#b9aa93')}
 rect(W*.549,H*.47,W*.056,H*.15,'#778680');ellipse(W*.577,H*.468,W*.028,H*.043,'#778680');
 // side banners and walls
 for(let x of [.09,.82]){rect(W*x,H*.31,W*.10,H*.44,'#d9ceb1');for(let n=0;n<6;n++)line(W*x,H*(.36+n*.065),W*(x+.1),H*(.36+n*.065),'#a7a58a65',2);rect(W*(x-.008),H*.285,W*.116,H*.035,'#eadcbc');polygon([[W*(x+.027),H*.32],[W*(x+.074),H*.32],[W*(x+.068),H*.52],[W*(x+.051),H*.55],[W*(x+.033),H*.52]],x<.2?'#507e9a':'#8c5d89');line(W*(x+.05),H*.34,W*(x+.05),H*.5,'#e4d4a5',2)}
 polygon([[0,H*.57],[W,H*.57],[W,H],[0,H]],'#68965d');
 // main path
 const roadLeftTop=W*.47,roadRightTop=W*.54,roadLeftBottom=W*.18,roadRightBottom=W*.86;polygon([[roadLeftTop,H*.59],[roadRightTop,H*.59],[roadRightBottom,H],[roadLeftBottom,H]],'#d4c39c');polygon([[W*.487,H*.59],[W*.523,H*.59],[W*.68,H],[W*.32,H]],'#f0dfbe55');for(let i=0;i<14;i++){const d=i/14,y=H*(.61+d*d*.42);line(W*(.47-d*.30),y,W*(.54+d*.32),y,'#8b8067a0',1.6)}
 // varied garden trees
 const trees=[['#4e7650','#64895f',.08,.67,1],['#5d7e4a','#7a975a',.14,.63,.9],['#46664a','#63836c',.88,.66,1.1],['#5f8052','#87a164',.95,.61,.88]];
 for(const [dark,light,px,py,sc] of trees){const x=W*px,y=H*py;rect(x-W*.01*sc,y-H*.15*sc,W*.02*sc,H*.16*sc,'#70513c');for(let i=0;i<6;i++){const ox=(i%3-1)*W*.026*sc,oy=(Math.floor(i/3))*H*.04*sc;ellipse(x+ox,y-H*.18*sc+oy,W*.05*sc,H*.06*sc,i%2?light:dark)} }
 // hedges bordering the path
 for(let i=0;i<26;i++){let x=i*W/25;polygon([[x,H*.65],[x+W*.013,H*.41+(i%4)*H*.028],[x+W*.035,H*.65]],i%3===0?'#3c7657':'#518663')}
 // Bare grass, worn edges and scattered pebble texture only. No flowers on the ground.
 for(let i=0;i<180;i++){let fx=(i*121.31)%W,fy=H*(.67+((i*43.7)%100)/305);if(fy>=H)continue;const r=(fy/H-.59)/.41;const lx=roadLeftTop+(roadLeftBottom-roadLeftTop)*r,rx=roadRightTop+(roadRightBottom-roadRightTop)*r;
  if(fx>lx-12&&fx<rx+12){ellipse(fx,fy,1.4,1,'#978b72aa');continue}
  line(fx,fy+3,fx-2,fy+10,i%3===0?'#4a8154':'#427449',.65);
 }
 for(let i=0;i<22;i++){let x=(i*87+now*.014*(i%3+1))%(W+40),y=(i*177+Math.sin(now/1300+i)*18)%H;ellipse(x,y,2.5,5,'#fff9e8bf')}
}

function drawArena(now){if(roundIndex===1)woods(now);else if(roundIndex===2)tavern(now);else castle(now)}
// Paint the detailed level once per arena / screen size, instead of hundreds of paths every frame.
function buildArenaCache(){
  if(cacheRound===roundIndex&&cacheWidth===c.width&&cacheHeight===c.height)return;
  arenaCache.width=c.width;arenaCache.height=c.height;
  arenaCacheCtx.setTransform(dpr,0,0,dpr,0,0);
  const previous=g;g=arenaCacheCtx;
  try{
    drawArena(0);
    const shade=g.createLinearGradient(0,0,0,H);shade.addColorStop(0,'#172a312c');shade.addColorStop(.3,'#0000');shade.addColorStop(1,'#14281f48');rect(0,0,W,H,shade);
  }finally{g=previous}
  cacheRound=roundIndex;cacheWidth=c.width;cacheHeight=c.height;
}
// A handful of inexpensive animated dust motes keep the scenery feeling alive.
function ambientMotes(now){
  if(roundIndex===2)return;
  g.save();g.globalAlpha=.48;
  for(let i=0;i<12;i++){const x=(i*101+now*.016*(i%3+1))%(W+12),y=(i*79+Math.sin(now*.0009+i)*17)%(H*.85);ellipse(x,y,1.8,2.3,roundIndex===1?'#e5f2c4':'#fff3d1')}
  g.restore();
}
function woods(now){if(woodsImage.complete&&woodsImage.naturalWidth){g.drawImage(woodsImage,0,0,W,H)}else {const fall=g.createLinearGradient(0,0,0,H);fall.addColorStop(0,'#264f4b');fall.addColorStop(1,'#526047');rect(0,0,W,H,fall)}}
function tavern(now){
 const back=g.createLinearGradient(0,0,0,H);back.addColorStop(0,'#211a1a');back.addColorStop(.5,'#644635');back.addColorStop(.68,'#543c30');back.addColorStop(1,'#261915');rect(0,0,W,H,back);
 // Interior wall with limestone blocks and timber braces
 for(let j=0;j<12;j++)for(let i=0;i<18;i++){let x=(i+(j%2)*.5)*W/18,y=j*H*.055;rect(x+2,y+2,W/18-5,H*.055-5,(i+j)%4===0?'#705242':'#775847')}
 // oak ceiling + beams
 polygon([[0,0],[W,0],[W*.83,H*.28],[W*.17,H*.28]],'#30211d');for(let i=0;i<8;i++){let x=i*W/7;line(x,0,W*.5+(x-W*.5)*.5,H*.26,'#6e4931',13)}
 rect(0,H*.26,W,H*.037,'#32211a');line(0,H*.3,W,H*.3,'#9b72534e',3);
 // fireplace rear right
 rect(W*.67,H*.39,W*.23,H*.27,'#37231e');polygon([[W*.66,H*.41],[W*.70,H*.33],[W*.87,H*.33],[W*.91,H*.41]],'#766354','#aa8969',3);
 rect(W*.697,H*.43,W*.173,H*.235,'#1e1112');let glow=g.createRadialGradient(W*.78,H*.57,5,W*.78,H*.59,W*.19);glow.addColorStop(0,'#ffc06d9b');glow.addColorStop(1,'#cf5d1300');rect(W*.61,H*.3,W*.37,H*.5,glow);
 for(let i=0;i<5;i++){let bx=W*(.72+i*.029);polygon([[bx-12,H*.66],[bx+12,H*.66],[bx+7,H*(.53+i%2*.02)],[bx,H*(.485+i%2*.02)],[bx-9,H*(.56+i%2*.01)]],i%2?'#f5a23b':'#ffc979')}
 // arched stained windows left
 for(let x of [.1,.295]){rect(W*x,H*.35,W*.095,H*.245,'#231b1b');rect(W*(x+.008),H*.363,W*.079,H*.222,'#71969b');ellipse(W*(x+.0475),H*.368,W*.0395,H*.06,'#a9b1a3');line(W*(x+.0475),H*.35,W*(x+.0475),H*.59,'#49382b',7);line(W*(x+.008),H*.47,W*(x+.09),H*.47,'#49382b',7)}
 // right/left walls support posts
 for(let x of [.04,.23,.56,.94]){rect(W*x,H*.22,W*.027,H*.54,'#342119');line(W*(x+.007),H*.23,W*(x+.007),H*.67,'#89604459',4)}
 // long wooden floor, perspective plank details
 polygon([[0,H*.69],[W,H*.69],[W,H],[0,H]],'#4b3023');polygon([[W*.22,H*.69],[W*.79,H*.69],[W,H],[0,H]],'#725035');
 for(let i=0;i<21;i++)line(W*.5+(i-10)*W*.027,H*.69,W*.5+(i-10)*W*.085,H,'#2a1814',1.7);
 for(let i=0;i<7;i++){let y=H*(.7+i*i*.009);line(0,y,W,y,'#bc83543a',2)}
 // tavern seating on far edges; stay clear of dueling lane
 for(let side of[-1,1]){let x=side<0?W*.08:W*.89;polygon([[x-W*.085,H*.75],[x+W*.085,H*.75],[x+W*.11,H*.85],[x-W*.11,H*.85]],'#69472e','#291b15',3);polygon([[x-W*.065,H*.75],[x+W*.065,H*.75],[x+W*.043,H*.68],[x-W*.043,H*.68]],'#87603d','#c8a371',2);rect(x-W*.075,H*.84,W*.019,H*.16,'#35241b');rect(x+W*.057,H*.84,W*.019,H*.16,'#35241b');ellipse(x,H*.70,10,4,'#d3a05f')}
 // pendulum chandeliers hanging above the battleground
 for(let x of [.35,.67]){line(W*x,0,W*x,H*.23,'#1c1513',4);ellipse(W*x,H*.24,50,14,'#66503e');for(let i=-2;i<=2;i++){let cx=W*x+i*20;ellipse(cx,H*.235,4,9,'#ffdca3');g.save();g.shadowColor='#efaa5e';g.shadowBlur=18;ellipse(cx,H*.228,2.5,6,'#fff3b2');g.restore()}}
 // extra tavern props and dusty light grains
 for(let i=0;i<28;i++){let x=(i*137)%W,y=(i*71+Math.sin(now*.001+i)*9)%H;ellipse(x,y,1.7,1.7,'#e0ba6d55')}
 for(let s of [[.15,.79],[.83,.78],[.92,.77]]){let x=W*s[0],y=H*s[1];ellipse(x,y,24,10,'#5f402b');rect(x-20,y-48,40,46,'#6d4a32');rect(x-4,y-56,8,10,'#2b1a14');}
 for(let x of [.16,.27,.74,.86]){polygon([[W*x,H*.63],[W*(x+.025),H*.61],[W*(x+.03),H*.67],[W*(x-.008),H*.69]],'#725b46','#b49167',2)}
}
function drawEnemyCircle(now){
 if(!s||s.phase!=='windup')return;
 const k=Math.max(.86,Math.min(1.68,W/1030,H/628));const x=W*.5,y=H*.59-112*k,r=148*k;
 const progress=isOnline?(s.onlineEnemyProgress||0):Math.max(0,Math.min(1,(now-s.windupStart)/2400)),angle=-Math.PI/2+progress*Math.PI*2;
 g.save();g.translate(x,y);
 g.shadowColor='#ff774c';g.shadowBlur=18;g.beginPath();g.arc(0,0,r+7,0,Math.PI*2);g.lineWidth=Math.max(7,10*k);g.strokeStyle='#a23b3670';g.stroke();g.shadowBlur=0;
 g.beginPath();g.arc(0,0,r,0,Math.PI*2);g.lineWidth=18*k;g.strokeStyle='#1a1720c7';g.stroke();
 g.beginPath();g.arc(0,0,r,-Math.PI/2,angle);g.strokeStyle='#ffb178';g.lineCap='round';g.lineWidth=16*k;g.shadowBlur=20;g.shadowColor='#ff835a';g.stroke();g.shadowBlur=0;
 g.beginPath();g.arc(0,0,r-15*k,0,Math.PI*2);g.lineWidth=2*k;g.strokeStyle='#ffe3b777';g.stroke();
 for(let i=0;i<36;i++){let a=-Math.PI/2+i*Math.PI*2/36;let big=i%3===0;line(Math.cos(a)*(r+17*k),Math.sin(a)*(r+17*k),Math.cos(a)*(r+(big?29:22)*k),Math.sin(a)*(r+(big?29:22)*k),i/36<=progress?'#ffe6b3':'#90756b',big?3.5*k:1.8*k)}
 // centered notification at the base of the ring
 let text=s.enemyZone.toUpperCase()+' ATTACK';g.textAlign='center';g.font='700 '+Math.max(12,14*k)+'px Arial';g.shadowColor='#1c1014';g.shadowBlur=8;g.fillStyle='#fff1d6';g.fillText(text,0,r+52*k);
 g.restore();
}

