 const winnerIsPlayer=ceremonyWinner===playerKnight;const champWpm=winnerIsPlayer?ceremonyWpm.player:ceremonyWpm.enemy;const lossWpm=winnerIsPlayer?ceremonyWpm.enemy:ceremonyWpm.player;
