function draw(now){
  buildArenaCache();
  g=screenCtx;
  g.clearRect(0,0,W,H);
  g.save();
  if(s)g.translate(rnd(-s.shake,s.shake),rnd(-s.shake,s.shake));
  g.drawImage(arenaCache,0,0,W,H);
  ambientMotes(now);
  if(s){
    drawEnemyCircle(now);
    foe(now);
    povSword(now);
    drawShield(now);
    for(const p of s.particles){g.globalAlpha=Math.min(1,p.life/14);rect(p.x,p.y,4,4,p.color)}
    g.globalAlpha=1;
  }
  g.restore();
}
let lastCeremonyDraw=0;function frame(realNow){
 if(paused){const remaining=Math.max(0,10-(realNow-pauseStartReal)/1000);updatePauseClock(remaining);if(remaining<=0)resumeGame();else{requestAnimationFrame(frame);return}}
 const now=gameTime(),dt=Math.max(0,Math.min(50,now-last));last=now;
 update(now,dt);
 if(victoryTransitionActive && now-victoryTransitionAt>=2900)finishVictoryTransition();
 if(ceremonyActive){if(now-lastCeremonyDraw>=30){drawCeremony(now);lastCeremonyDraw=now}}else draw(now);
 requestAnimationFrame(frame)
}requestAnimationFrame(frame);

// Room lobby and networked combat. The server validates the words, damage, guards and scoring.
function sendOnline(payload){if(onlineWS?.readyState===1)onlineWS.send(JSON.stringify(payload))}
function escapeHtml(s){return String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function startConnection(kind){
 const name=$('knightName').value.trim().slice(0,20);if(!name){$('entryStatus').textContent='Enter your player name to continue.';$('knightName').focus();return}onlineName=name;
 const code=$('roomCode').value.trim().toUpperCase();if(kind==='join'&&!/^[A-Z2-9]{4}$/.test(code)){$('entryStatus').textContent='Enter the four-character room code.';return}
 if(location.protocol==='file:'){$('entryStatus').textContent='Online play needs the hosted game server. Open this through npm start or the published URL.';return}
 $('entryStatus').textContent='Connecting securely to the duel server…';
 const socket=new WebSocket((location.protocol==='https:'?'wss://':'ws://')+location.host+'/');onlineWS=socket;
 socket.onopen=()=>sendOnline({type:kind,name,code});
 socket.onerror=()=>{$('entryStatus').textContent='Could not reach the game server. Try again.'};
 socket.onclose=()=>{if(!isOnline){$('entryStatus').textContent='Connection closed. Try again.'}else {alert('Connection to the duel server closed. Please reload to reconnect.');location.reload()}};
 socket.onmessage=e=>{let v;try{v=JSON.parse(e.data)}catch{return}handleOnline(v)};
}
function handleOnline(msg){
 if(msg.type==='error'){$('entryStatus').textContent=msg.message;return}
 if(msg.type==='disconnected'){$('readyHeading').textContent='OPPONENT DISCONNECTED';$('readyStatus').textContent=msg.message;$('readyScreen').hidden=false;return}
 if(msg.type==='joined'){
   isOnline=true;onlineRoom=msg.code;onlineIndex=msg.index;
   $('entryScreen').hidden=true;$('roomScreen').hidden=false;
   $('roomBigCode').textContent=msg.code;$('readyCode').textContent=msg.code;$('onlineRoomTag').textContent=msg.code;$('onlineTag').hidden=false;
   history.replaceState({},'',location.pathname+'?room='+encodeURIComponent(msg.code));
   return;
 }
 if(msg.type==='state'){
   onlineState=msg;onlineEnemyKnight=msg.enemy.knight||'obsidian';
   $('roomPlayers').innerHTML='<strong>'+escapeHtml(msg.me.name)+'</strong> '+(msg.enemy.name?'<span> vs </span><strong>'+escapeHtml(msg.enemy.name)+'</strong>':' · Waiting for knight #2');
   if(msg.roomPhase==='lobby'){$('readyStatus').textContent=msg.enemy.name?'Both knights are here. Waiting for selections.':'Waiting for your friend to join room '+onlineRoom+'.';return}
   if(msg.roomPhase==='intro' || msg.roomPhase==='battle'){
      $('roomScreen').hidden=true;$('readyScreen').hidden=true;
      if(onlineRound!==msg.round){onlineRound=msg.round;roundResults=(msg.scores[0]+msg.scores[1]===0)?[]:roundResults;startOnlineRound(msg)}
      updateOnlineSnapshot(msg);return;
   }
   if(msg.roomPhase==='round_end'){
      if(msg.events){for(const ev of msg.events)if(ev.type==='round_end'&&ev.id>onlineLastEvent){const iWon=ev.winner===onlineIndex;roundResults.push(iWon);$('roundSplashTitle').textContent=iWon?'ROUND WON':'ROUND LOST';$('roundSplashNext').textContent='FIRST TO TWO WINS';$('roundSplash').hidden=false}}
      for(const ev of msg.events||[])onlineLastEvent=Math.max(onlineLastEvent,ev.id);
      return;
   }
   if(msg.roomPhase==='finished'&&!onlineFinished){
      onlineFinished=true;$('roundSplash').hidden=true;$('countdown').classList.remove('on');$('matchScore').classList.remove('active');
      if(s)s.playing=false;
      const win=msg.finishedWinner===onlineIndex,ours=msg.scores[onlineIndex],theirs=msg.scores[1-onlineIndex];
      roundResults=[];for(const ev of msg.events||[])if(ev.type==='round_end'||ev.type==='match_end')roundResults.push(ev.winner===onlineIndex);
      startVictoryTransition(win,ours,theirs);
   }
 }
}
function startOnlineRound(msg){
 playerKnight=msg.me.knight;onlineEnemyKnight=msg.enemy.knight;
 if(msg.round===0)resetMatchStats();roundResults=Array(msg.scores[onlineIndex]).fill(true).concat(Array(msg.scores[1-onlineIndex]).fill(false));
 $('roundSplash').hidden=true;startRound(msg.round);
 s.battleStartsAt=gameTime()+Math.max(0,msg.startAt-msg.serverNow);
 s.preparationStart=s.battleStartsAt-3600;
 $('countPlace').textContent=roundLabel(msg.round);
}
function updateOnlineSnapshot(msg){
 if(!s)return;
 const me=msg.me,enemy=msg.enemy;const adjusted=ts=>ts?gameTime()+ts-msg.serverNow:0;
 beginMatchStats();
 if(me.word!==matchStats.lastMeWord||me.typed.length<matchStats.lastMeLen)matchStats.lastMeLen=0;
 if(enemy.word!==matchStats.lastEnemyWord||enemy.typed.length<matchStats.lastEnemyLen)matchStats.lastEnemyLen=0;
 if(me.typed.length>matchStats.lastMeLen)addTypedChars('player',me.typed.length-matchStats.lastMeLen);
 if(enemy.typed.length>matchStats.lastEnemyLen)addTypedChars('enemy',enemy.typed.length-matchStats.lastEnemyLen);
 matchStats.lastMeLen=me.typed.length;matchStats.lastEnemyLen=enemy.typed.length;matchStats.lastMeWord=me.word;matchStats.lastEnemyWord=enemy.word;
 s.myhp=me.hp;s.foehp=enemy.hp;
 s.word=me.word;s.words=[me.word];s.typed=me.typed;s.queue=me.queue.slice(0,5);s.strikes=me.hits;
 s.zone=me.zone;s.enemyZone=enemy.zone;s.blockTo=adjusted(me.blockUntil);s.blockReady=adjusted(me.blockReady);s.guardStart=s.blockTo?Math.max(0,s.blockTo-2000):0;
 s.feedback=me.feedback;s.feedbackUntil=adjusted(me.feedbackUntil);
 s.enemyWord=enemy.word;s.onlineEnemyProgress=enemy.word?enemy.typed.length/enemy.word.length:0;
 s.phase=enemy.typed.length>0?'windup':'wait';s.windupStart=gameTime()-s.onlineEnemyProgress*2400;
 s.battleStartsAt=gameTime()+Math.max(0,msg.startAt-msg.serverNow);
 // Live local-event effects are triggered once, never once per snapshot.
 for(const ev of msg.events||[]){if(ev.id<=onlineLastEvent)continue;onlineLastEvent=ev.id;
   if(ev.type==='swing'&&ev.actor===onlineIndex){s.attackStart=gameTime();s.attackSide=ev.zone;s.attackFrom={...s.pose};s.swingUntil=gameTime()+820}
   if(ev.type==='swing'&&ev.actor!==onlineIndex){s.enemySwing=gameTime()+680}
   if(ev.type==='hit'&&ev.actor===onlineIndex){s.foeStaggerStart=gameTime();s.foeStaggerUntil=gameTime()+600;particles(W*.5,H*.45,'#fff1cc',14)}
   if(ev.type==='hit'&&ev.actor!==onlineIndex){s.hitTo=gameTime()+450;s.shake=9;particles(W*.5,H*.62,'#ff9e7c',14);notify('WOUNDED · 12 DAMAGE','#ff9986',700)}
   if(ev.type==='interrupted'&&ev.target===onlineIndex)s.interruptUntil=gameTime()+1000;
   if(ev.type==='interrupted'&&ev.actor===onlineIndex)s.enemyInterruptUntil=gameTime()+950;
   if(ev.type==='blocked'){s.blocked=gameTime()+550;if(ev.target===onlineIndex)notify('BLOCKED','#c4f1ee',650)}
 }
 hud();
}
function onlineKey(e){if(!isOnline||onlineFinished||!onlineState||onlineState.roomPhase!=='battle'||e.repeat||e.ctrlKey||e.metaKey||e.altKey)return;
 const key=String(e.key).toLowerCase();const zone={a:'left',w:'center',d:'right'}[key];
 if(zone){s.zone=zone;sendOnline({type:'action',action:'stance',zone})}
 if(e.key===' '){sendOnline({type:'action',action:'block'});return}
 if(/^[a-z]$/.test(key)){sendOnline({type:'action',action:'key',key})}
}
function updateOnline(now,dt){
 if(onlineState?.roomPhase!=='battle'&&onlineState?.roomPhase!=='intro')return;
 if(now<s.battleStartsAt){
  const seconds=(now-(s.battleStartsAt-3600))/1000;
  const countText=seconds<1?'3':seconds<2?'2':seconds<3?'1':'DUEL!';$('countNumber').textContent=countText;
  $('countdown').classList.add('on');return;
 }
 $('countdown').classList.remove('on');
 const target=stancePose(s.zone),blend=1-Math.exp(-dt/120);
 s.pose.x+=(target.x-s.pose.x)*blend;s.pose.y+=(target.y-s.pose.y)*blend;s.pose.a+=(target.a-s.pose.a)*blend;
 if(now-lastHudTick>=100){lastHudTick=now;updateGuardUI(now)}
 $('hurt').style.opacity=now<s.hitTo?'1':'0';$('interrupt').classList.toggle('on',now<s.interruptUntil);$('enemyInterrupt').classList.toggle('on',now<s.enemyInterruptUntil);
 $('foeTyping').classList.toggle('on',s.phase==='windup');$('foeTyping').textContent=s.phase==='windup'?'ENEMY TYPING · '+onlineState.enemy.typed.toUpperCase()+'▌':'';
 if(now>toastExpire)$('toast').classList.remove('on');s.particles=s.particles.filter(p=>p.life>0);for(const p of s.particles){p.x+=p.vx*dt/16;p.y+=p.vy*dt/16;p.vy+=.14*dt/16;p.life-=dt/16}s.shake*=.87;
}
